INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('cd0ea3f6-7cb7-44ae-9611-2d07b562bc66', '21feff02-016d-46e2-bb9d-c27495133b1b', '120. óra: Grafikonok, diagramok, összefüggések', 'Oszlopdiagram, vonaldiagram, pontdiagram és táblázat olvasása.', 'Matematika', '6. osztály', 'Statisztika', '[{"id": "c545d294-3724-41d4-b53d-98cff8aa56b4", "text": "Mire alkalmas leginkább a vonaldiagram (grafikon)?", "type": "multiple-choice", "options": [{"id": "89f012b8-b4a1-454f-9bda-cc42897ebc5f", "text": "Folytonos adatok (pl. hőmérséklet) időbeli változásának szemléltetésére", "isCorrect": true}, {"id": "0532c1e5-a6df-47b8-886b-ff13c5da10e9", "text": "Egyetlen szám felírására", "isCorrect": false}, {"id": "bdd3c044-51d5-49e2-a415-05a495f7d536", "text": "Betűk csoportosítására", "isCorrect": false}, {"id": "1ede2d4d-616d-45d9-94a5-18c532db55d8", "text": "Körök osztására", "isCorrect": false}], "timeLimit": 15}, {"id": "e4e2f887-dc7a-4780-bc66-d44d9958630d", "text": "Mire alkalmas az oszlopdiagram?", "type": "multiple-choice", "options": [{"id": "79c0a452-a469-43ef-9c7d-654e3937523f", "text": "Különböző kategóriák mennyiségének gyors összehasonlítására oszlopok magasságával", "isCorrect": true}, {"id": "e449bc6d-27ba-4854-88a7-652a467e12df", "text": "Számok összeadására", "isCorrect": false}, {"id": "a75f1677-4569-424e-90db-930708c7fc21", "text": "Csak 2 adat ábrázolására", "isCorrect": false}, {"id": "ce7c7913-3748-43bd-819f-b878304a18ac", "text": "Videónézésre", "isCorrect": false}], "timeLimit": 15}, {"id": "0bd96679-6a4f-43de-a341-e518cfffc362", "text": "Ha a diagramon az 1 cm-es oszlop 5 tanulót jelent, hány tanulót jelent a 4 cm-es oszlop?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "6b9a39d9-5fbd-42bc-b923-c3e1e79979b0", "text": "A diagramok tengelyein jelölni kell a skálát és a mértékegységet.", "type": "true-false", "options": [{"id": "349b54f7-7fc0-452c-938d-941e56a8e4ca", "text": "Igaz", "isCorrect": true}, {"id": "40d5a45d-48dd-46e6-8620-81a346592f8e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d40001d9-a237-4675-9dcc-4176aef15c0e", "text": "A táblázat soraiból és oszlopaiból pontos értékek olvashatók le.", "type": "true-false", "options": [{"id": "950ffe48-c99d-4306-9807-e15797135f54", "text": "Igaz", "isCorrect": true}, {"id": "6680c8c5-5592-4714-b767-13403fbd90f9", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "afc2d838-0f0f-46a2-bf70-9034d39180e3", "text": "A hibásan skálázott grafikon félrevezetheti az olvasót.", "type": "true-false", "options": [{"id": "b5ba7841-76b6-415a-bf37-5ce051277336", "text": "Igaz", "isCorrect": true}, {"id": "ace22d53-3619-4137-a24b-7824b2ef2832", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "8cd3406c-0902-4fc1-9571-bf440a32a99b", "text": "Melyik a legmagasabb hőmérséklet, ha a heti mérések: 12°C, 15°C, 18°C, 14°C, 16°C?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "18"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('d5c1b59b-5c68-4796-8b5b-9098c5540b56', '21feff02-016d-46e2-bb9d-c27495133b1b', '121. óra: Kördiagram', 'Kördiagram értelmezése, körcikkek szöge, százalékos megoszlás.', 'Matematika', '6. osztály', 'Statisztika', '[{"id": "ac83a05d-1b48-4c6c-9088-c667b53e2345", "text": "Mire szolgál a kördiagram?", "type": "multiple-choice", "options": [{"id": "2124ea7f-6c89-40fb-a69f-1dd990468f32", "text": "Az egyes részek teljes egészhez (100%) viszonyított arányának szemléltetésére", "isCorrect": true}, {"id": "e4799ab9-c8c4-4919-9919-9cb6dda86ad9", "text": "Vonalak összekötésére", "isCorrect": false}, {"id": "220dab5d-e750-4294-ae82-b12a56d2b038", "text": "Pontok rajzolására", "isCorrect": false}, {"id": "36c48f53-44d8-48f3-aca0-a50d7aacaad9", "text": "Időbeli növekedés ábrázolására", "isCorrect": false}], "timeLimit": 15}, {"id": "a76f4ddd-4ebf-461d-a052-88085c42b6a2", "text": "Hány fokos a kördiagram teljes köre (100%)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "360"}, {"id": "15fe9e0b-0f55-4888-9d7f-fe2a2089c993", "text": "Hány fokos körcikk tartozik az 50%-os (fél) részhez? (360 / 2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "180"}, {"id": "079a7fec-0688-4889-9c35-6e3a0ffb08d0", "text": "Hány fokos körcikk tartozik a 25%-os (negyed) részhez? (360 / 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "34bb7f40-f63a-4d63-9d21-fcaa6b807ebb", "text": "Hány fokos körcikk tartozik a 10%-os részhez? (360 / 10)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "36"}, {"id": "445708d3-17df-43f9-a854-c61f33a81f75", "text": "A kördiagramon a körcikkek középponti szögei egyenesen arányosak a képviselt százalékkal.", "type": "true-false", "options": [{"id": "e5555f7d-bebb-4862-8378-4c11ae62ef76", "text": "Igaz", "isCorrect": true}, {"id": "811f2482-1bda-41a1-a49b-9865b89bbf06", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "fcb5ca25-21a2-4fea-a69e-0a637e987fab", "text": "A körcikkek szögeinek összege mindig 360°.", "type": "true-false", "options": [{"id": "859a4294-9493-449f-9a4a-6336e76a5aca", "text": "Igaz", "isCorrect": true}, {"id": "ca67957f-d194-4d92-bb3f-2300620f893a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('54412130-50c0-4980-9c20-ef91291242f7', '21feff02-016d-46e2-bb9d-c27495133b1b', '122. óra: Adatok ábrázolása, átlag', 'Számtani közép (átlag) kiszámítása és ábrázolás digitális eszközzel.', 'Matematika', '6. osztály', 'Statisztika', '[{"id": "59a6fc8d-564f-4898-9b11-d902d7b6ece7", "text": "Hogyan számítjuk ki több szám számtani középértékét (átlagát)?", "type": "multiple-choice", "options": [{"id": "376daeb8-ee1b-415a-af77-ec1745eccec5", "text": "Összeadjuk az adatokat, majd az összeget elosztjuk az adatok darabszámával", "isCorrect": true}, {"id": "34300b08-8b50-45bc-aaa9-38f811f4271c", "text": "Megszorozzuk az adatokat", "isCorrect": false}, {"id": "a715e5a7-e586-4a99-8f5f-7363851e81fc", "text": "Kivonjuk a legkisebbet a legnagyobból", "isCorrect": false}, {"id": "de97ba43-8f1c-4ccb-ad74-4102cccbcca2", "text": "Kiválasztjuk a leggyakoribb számot", "isCorrect": false}], "timeLimit": 15}, {"id": "d93b029f-bbed-4fc1-8ced-82f2cebc9677", "text": "Mennyi a 4, 6, 8, 10 számok átlaga? (28 / 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "7"}, {"id": "b6f931dd-f759-4f7a-86f0-ed0920463bc7", "text": "Mennyi a 10, 20, 30, 40, 50 számok átlaga? (150 / 5)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "a5831db1-7af5-45b2-933b-e02dadedcc21", "text": "Egy diák osztályzatai: 5, 4, 5, 5, 3. Mennyi a tanulmányi átlaga? (22 / 5)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4.4"}, {"id": "2e71338d-a3cd-46cd-8b76-0cc35f39c3c9", "text": "Az átlag értéke mindig a legkisebb és a legnagyobb adat közé esik.", "type": "true-false", "options": [{"id": "e820e14d-a696-4710-a5fb-af925aff9436", "text": "Igaz", "isCorrect": true}, {"id": "9d7a1ed9-8923-4d52-b273-5e613d806bdc", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d782214a-88f8-4484-8026-ba8cc158a9de", "text": "Digitális táblázatkezelőben (pl. Excel) az ÁTLAG (AVERAGE) függvény azonnal kiszámolja az átlagot.", "type": "true-false", "options": [{"id": "bf4f7530-572c-4e92-bc46-b6ca6d05e1db", "text": "Igaz", "isCorrect": true}, {"id": "60cd0b80-e2f6-4dda-80f7-40e67924365f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "bf5a9aad-e989-4bc4-a42c-eb78db892f97", "text": "Mennyi a 15 és 25 számtani közepe?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('18c136bd-b0c2-47ad-aa1f-c4fccaf44d3c', '21feff02-016d-46e2-bb9d-c27495133b1b', '123. óra: Dobáljunk kockákat!', 'Kísérletezés dobókockával, gyakoriság, relatív gyakoriság és valószínűség.', 'Matematika', '6. osztály', 'Statisztika', '[{"id": "6d457ca2-2f4b-4475-879e-0e8d30b71e2e", "text": "Egy szabályos 6 oldalú dobókockával mekkora az esélye a 6-os dobásnak?", "type": "multiple-choice", "options": [{"id": "8e1feac2-583e-411b-97cf-a237cc608be0", "text": "1 a 6-ból (1/6)", "isCorrect": true}, {"id": "dab6b3f3-7ea3-43df-a79c-7e400d95c4cd", "text": "1 a 2-ből", "isCorrect": false}, {"id": "9c6d3d05-5324-472b-9b2d-f3cafb824c66", "text": "100%", "isCorrect": false}, {"id": "3d6d37e1-b2e5-4042-8e32-ac06778d755a", "text": "0%", "isCorrect": false}], "timeLimit": 15}, {"id": "4a4e0b97-8f84-4de0-8af7-b3cf72efbdec", "text": "Mennyi a páros szám (2, 4, 6) dobásának valószínűsége dobókockával?", "type": "multiple-choice", "options": [{"id": "bd281e9e-2d15-4cce-af38-53261d037bb0", "text": "3 a 6-ból (3/6 = 1/2 azaz 50%)", "isCorrect": true}, {"id": "4ed903a8-2519-434f-8d0a-4f365ad63d38", "text": "1/6", "isCorrect": false}, {"id": "2eef68a6-e53a-41db-8aa7-5fdce163de79", "text": "2/6", "isCorrect": false}, {"id": "8100a0af-38fd-4ca0-bf0e-008b04f410eb", "text": "100%", "isCorrect": false}], "timeLimit": 15}, {"id": "c0a3ee92-cc5b-4c32-bcfa-703011bdb742", "text": "Sok dobási kísérlet végrehajtásakor a relatív gyakoriság megközelíti az elméleti valószínűséget.", "type": "true-false", "options": [{"id": "1d272140-6310-4905-a78d-f4e555eb419b", "text": "Igaz", "isCorrect": true}, {"id": "8cde9d71-29df-40b6-808b-879b087ab241", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "4d3c0d40-eddf-40e3-9b28-e1889ccf6756", "text": "Milyen esemény egy kockával 7-est dobni?", "type": "multiple-choice", "options": [{"id": "10aec65d-9b18-46b1-91b8-3b0aca2d813b", "text": "Lehetetlen esemény (0%)", "isCorrect": true}, {"id": "a6f3624f-a4e4-45d0-9fda-7930b1b7e1c0", "text": "Biztos esemény", "isCorrect": false}, {"id": "07847bc0-fde3-45a6-a8dc-88f383178e08", "text": "Lehetséges", "isCorrect": false}, {"id": "33f2c31d-8ac3-4db2-ab85-377ece29c3be", "text": "Véletlen", "isCorrect": false}], "timeLimit": 15}, {"id": "6e890ed0-8eb4-4ee2-bfbf-f5b8f155f2a8", "text": "Milyen esemény egy kockával 1 és 6 közötti számot dobni?", "type": "multiple-choice", "options": [{"id": "ce12ff63-5366-4443-a0af-dc00cbcc88c5", "text": "Biztos esemény (100%)", "isCorrect": true}, {"id": "f62ed211-b53e-456e-8e3c-83baf2661999", "text": "Lehetetlen", "isCorrect": false}, {"id": "efed3443-ee13-4dd2-b37a-c50d5a24f97d", "text": "Kétes", "isCorrect": false}, {"id": "860d8444-4fdf-4bbc-afde-c0d8c9cec1b5", "text": "Ritka", "isCorrect": false}], "timeLimit": 15}, {"id": "1d717e91-787d-494b-a0ab-2d6cf1b9849e", "text": "Hányféle kimenetele lehet két kocka dobásakor a kapott összegeknek? (2-től 12-ig: 11-féle)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "11"}, {"id": "abab5b30-864b-4221-abee-141d9a704384", "text": "Két kockával a leggyakoribb dobási összeg a 7.", "type": "true-false", "options": [{"id": "b7c1fc58-b738-4980-9176-d38e85f583ad", "text": "Igaz", "isCorrect": true}, {"id": "bbed5436-5887-4b97-b33e-871d11251a1b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('eb6de54f-33d8-4ab6-9109-f0325d65c68c', '21feff02-016d-46e2-bb9d-c27495133b1b', '124. óra: Dobáljunk pénzérmét!', 'Kísérletezés érmével, fej vagy írás, tapasztalati valószínűség.', 'Matematika', '6. osztály', 'Statisztika', '[{"id": "76205f7b-6166-48ee-8432-77462f2b1997", "text": "Egy szabályos pénzérme feldobásakor mekkora a fej dobás valószínűsége?", "type": "multiple-choice", "options": [{"id": "6917a328-3f4b-4299-b575-4383e27d0117", "text": "1 a 2-ből (1/2 azaz 50%)", "isCorrect": true}, {"id": "1e3fe8da-a3de-4e03-a46f-bef7cc47bcf2", "text": "1/4", "isCorrect": false}, {"id": "1d55baa3-a8c1-4add-82f9-984e5ba107e7", "text": "100%", "isCorrect": false}, {"id": "78bb3d14-6bac-4331-a334-50acf15a1480", "text": "0%", "isCorrect": false}], "timeLimit": 15}, {"id": "39d1df82-9316-4aae-bdd1-896bae6c0ffb", "text": "Ha 100-szor dobunk fel egy érmét, a fej dobások száma kb. 50 körül várható.", "type": "true-false", "options": [{"id": "295d8b5a-a672-45ca-97c8-f8405ab48846", "text": "Igaz", "isCorrect": true}, {"id": "7e218775-f6a3-4371-8fe3-44a100ad314a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "46ccae66-ef77-433e-8f0b-07a9cd10e44b", "text": "Hány kimenetele lehet 2 érme egyidejű feldobásának? (FF, FI, IF, II)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "1df23f1c-7261-46d7-92d5-47f6d752c2cb", "text": "Mekkora a valószínűsége annak, hogy 2 érmével mindkettő fej lesz? (1 a 4-ből = 25%)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "25"}, {"id": "8ef2ac71-7ebf-4a7a-a33b-07599a1ae440", "text": "A véletlen kísérletek eredményét az egyes próbálkozásoknál nem lehet pontosan kiszámítani, de nagy számnál szabályszerűség mutatkozik.", "type": "true-false", "options": [{"id": "ad4db91b-b281-44ba-9121-749c30eac01a", "text": "Igaz", "isCorrect": true}, {"id": "7eca0154-7322-4deb-84e4-ca7bd6963e1e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "5b34a096-7ef3-46ce-9650-052c8e211fcb", "text": "A biztos esemény valószínűsége 100% (vagy 1).", "type": "true-false", "options": [{"id": "cd3cbf55-d99d-4b1b-89a8-623e8f1a6fe4", "text": "Igaz", "isCorrect": true}, {"id": "ff43e3c6-f295-4b8b-86ca-0452acebda43", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "4b993d86-29ca-4a15-b154-3c8c56fe5075", "text": "A lehetetlen esemény valószínűsége 0% (vagy 0).", "type": "true-false", "options": [{"id": "ff5e77f5-52f3-4d0a-b2c9-dc476e5eb6fa", "text": "Igaz", "isCorrect": true}, {"id": "9d2fae13-12db-4881-8ddb-419285b61a73", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('b2213b4b-4887-4767-92f7-ab286250b358', '21feff02-016d-46e2-bb9d-c27495133b1b', '125. óra: Összefoglalás', 'Statisztikai és valószínűségi ismeretek összefoglalása.', 'Matematika', '6. osztály', 'Statisztika', '[{"id": "a129a2da-720a-43d0-80f7-5276e869af0b", "text": "Mennyi a 6, 8, 10, 12 számok átlaga? (36 / 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "9"}, {"id": "8a02e869-9ff0-4c6c-9edf-40f82f29f09c", "text": "Hány fokos körcikk felel meg a kördiagramon a 50%-nak?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "180"}, {"id": "9c4f440c-cf2c-4193-905e-6b87624c7cbd", "text": "Hány fokos körcikk felel meg a kördiagramon a 25%-nak?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "acb6e999-ed2a-4b8e-9544-297814f270d3", "text": "Egy kockával 6-ost dobni 1/6 valószínűségű esemény.", "type": "true-false", "options": [{"id": "92f7eee8-8e12-4e86-83d4-5c1110476c69", "text": "Igaz", "isCorrect": true}, {"id": "bb4e1778-e69e-4b16-8eb3-0db12af19470", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "cc9ef35b-0f88-4432-83cd-9a563bc89ef2", "text": "Az adatok átlagához az összes adat összegét elosztjuk a darabszámmal.", "type": "true-false", "options": [{"id": "5fc469eb-8132-4bba-b57d-5358243a2ee3", "text": "Igaz", "isCorrect": true}, {"id": "71a8cf7a-f788-4476-b66d-16dd9f5273ca", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "7f9a223b-f68a-43b0-8a9b-4bb9a935d3ad", "text": "Melyik grafikon alkalmas időbeli változás ábrázolására?", "type": "multiple-choice", "options": [{"id": "d709007a-acd0-426c-9080-439eed600b3c", "text": "Vonaldiagram", "isCorrect": true}, {"id": "fb18db8b-17ce-44cf-9c78-07b9c7902378", "text": "Kördiagram", "isCorrect": false}, {"id": "35f0dc9b-2399-4a1c-a563-c693ac419d22", "text": "Pontdiagram", "isCorrect": false}, {"id": "3df49372-4b03-4a95-ae67-9b12332ad4f7", "text": "Képrejtvény", "isCorrect": false}], "timeLimit": 15}, {"id": "749e7e21-f773-4232-ae50-97c101f548f7", "text": "Mennyi a 20 és 40 számtani közepe?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('6f10a040-f960-479a-bcbb-b97a0d54a899', '21feff02-016d-46e2-bb9d-c27495133b1b', '126. óra: Számonkérés', 'Számonkérés projektmunka és teszt formájában a Statisztikából (10 kérdés).', 'Matematika', '6. osztály', 'Statisztika', '[{"id": "68b1e63a-3d61-483b-a044-7687d2e43e62", "text": "1. Mennyi a 10, 20, 30 számok átlaga?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "09a7a50b-2c8b-4918-84a6-c851782b7309", "text": "2. Mennyi a 2, 4, 6, 8, 10 számok átlaga?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "3d4e9ad9-cb1c-44b6-a169-fdf5d9b398bd", "text": "3. Hány fokos a teljes kör a kördiagramon?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "360"}, {"id": "b470987a-dcbc-423c-a4fe-dcfc1031ec39", "text": "4. Hány fokos körcikk jelöli a 10%-ot a kördiagramon?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "36"}, {"id": "00ed34b4-be47-4e9c-a681-3aa299459e4f", "text": "5. Mekkora a fej dobás valószínűsége százalékban egy szabályos érmével?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "50"}, {"id": "23c51f33-7a86-4bbb-acbe-29fd2b4f903a", "text": "6. Milyen esemény egy 6 oldalú kockával 8-ast dobni?", "type": "multiple-choice", "options": [{"id": "eb77a2a9-0d5f-4fdc-b117-8d5c86ed91ff", "text": "Lehetetlen esemény", "isCorrect": true}, {"id": "f5424b5d-b1b4-4c35-81c0-4a78c1417f43", "text": "Biztos esemény", "isCorrect": false}, {"id": "c8ed192e-3c7f-42c7-b480-be36cd9313b2", "text": "Lehetséges", "isCorrect": false}, {"id": "c21a3c34-d27b-429b-ba71-514497c49e25", "text": "Döntetlen", "isCorrect": false}], "timeLimit": 15}, {"id": "5752835f-0825-433a-b204-f617ec18c181", "text": "7. Milyen esemény egy 6 oldalú kockával 1 és 6 közötti számot dobni?", "type": "multiple-choice", "options": [{"id": "b80d3caa-0491-4384-9ba6-035d05ef0d58", "text": "Biztos esemény", "isCorrect": true}, {"id": "019f173c-dcad-4921-8fb5-697132b5557e", "text": "Lehetetlen esemény", "isCorrect": false}, {"id": "65386f5b-8aab-4c14-88c6-ec6d744d9192", "text": "Ritka", "isCorrect": false}, {"id": "60117e76-965c-4cbf-ba60-496d65665c28", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "645a2d55-7a78-4453-a2c6-f26f18011844", "text": "8. Az adatok átlaga mindig a legkisebb és legnagyobb adat közé esik.", "type": "true-false", "options": [{"id": "bbd89e5b-ec1b-4bcd-9a15-660975f1ad53", "text": "Igaz", "isCorrect": true}, {"id": "475737ef-f3e6-4f1c-8300-76d4952a4bac", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "52dcf70c-90aa-4ff1-9c76-43390c8ac445", "text": "9. Hány kimenetele lehet 2 érme feldobásának?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "53082f34-bfdf-41d8-a976-e825570da93a", "text": "10. A vonaldiagram az adatok időbeli alakulását mutatja meg jól.", "type": "true-false", "options": [{"id": "fe721341-8072-4da9-941b-87876263bb03", "text": "Igaz", "isCorrect": true}, {"id": "e2801bcc-7c16-48ee-8966-a52a0040f7c0", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('b32d12f8-b630-454a-9777-d2804022e542', '21feff02-016d-46e2-bb9d-c27495133b1b', '127. óra: A számonkérés értékelése', 'A statisztikai feladatok és projektmunkák megbeszélése, értékelése.', 'Matematika', '6. osztály', 'Statisztika', '[{"id": "59cc3ad2-8fac-4290-ac3f-d73a69034e1e", "text": "Mi volt a projektmunka és a számonkérés legfőbb tanulsága?", "type": "multiple-choice", "options": [{"id": "a88cf190-6b20-43b1-a00f-5137a0b79143", "text": "Az adatok pontos rögzítése és a helyes skálázás elengedhetetlen a helyes diagramokhoz", "isCorrect": true}, {"id": "e52d14f1-3ba0-4e33-a891-5ec008753242", "text": "A rajzolás nem fontos", "isCorrect": false}, {"id": "cd02c9c8-0fb4-4945-86d7-5b7ed43d1b21", "text": "A számolást el kell hagyni", "isCorrect": false}, {"id": "de7e4748-885c-4800-9af6-b830ae53f5ea", "text": "Mindegy a skála", "isCorrect": false}], "timeLimit": 15}, {"id": "bcb2f68c-d580-40e4-aee4-db58b69a6f28", "text": "Az átlag kiszámításánál a darabszámmal való osztást nem szabad elfelejteni.", "type": "true-false", "options": [{"id": "e6c76840-5ee6-4cf2-a5f9-3c3515167b2e", "text": "Igaz", "isCorrect": true}, {"id": "80add9f3-8b5b-4bb1-aee5-06331b9c0ee3", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d4125fb2-53c7-4508-81ed-295758d91d81", "text": "Mennyi a 12 és 18 számtani közepe?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "15"}, {"id": "06d01b72-b994-42ac-8f1c-bd7d6fa385a5", "text": "A kördiagram körcikkei összefüggenek a százalékos megoszlással.", "type": "true-false", "options": [{"id": "b7d38fb4-217b-45a5-b53b-5ed050fe7ccc", "text": "Igaz", "isCorrect": true}, {"id": "073366c5-b80f-4dee-b2b3-61629b53ea67", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "89e895ed-51bd-416b-bbe4-20233b6610a8", "text": "A kísérletek során nyert adatok segítenek megérteni a valószínűségi elveket.", "type": "true-false", "options": [{"id": "308d4980-de2a-448a-a147-15888b759533", "text": "Igaz", "isCorrect": true}, {"id": "c40492ff-0000-4cbe-a99f-7142c43829d9", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "9ff7635f-bc4d-4458-83a1-b0e85c61bc90", "text": "Mennyi a 5, 10, 15 átlaga?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "f8e2e27d-8b41-494e-a129-b483e498c27c", "text": "A csoporteredmények bemutatása fejlesztette a kommunikációs készséget.", "type": "true-false", "options": [{"id": "cf0dd20a-043e-4e7e-b5b6-495e84b8cc79", "text": "Igaz", "isCorrect": true}, {"id": "d6673c38-c24b-40c8-b231-2ad22be9da85", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('d925f79e-2aea-40c9-baa9-6778828d0a52', '21feff02-016d-46e2-bb9d-c27495133b1b', '128. óra: Mindennapi pénzügyeink I.', 'Alapvető pénzügyi fogalmak: megtakarítás, kamat, kamatláb, futamidő, bankbetét.', 'Matematika', '6. osztály', 'Mindennapi pénzügyeink', '[{"id": "3495c626-cfdf-46b7-9678-566929a38352", "text": "Mit jelent a banki megtakarítás (betét) után járó ''kamat''?", "type": "multiple-choice", "options": [{"id": "75f851b4-4c8c-4541-8f7a-7274c51f8cdf", "text": "A bank által a lekötött pénz használatáért fizetett plusz összeg", "isCorrect": true}, {"id": "6c7f0af0-c98d-4b32-8238-da0f75690f56", "text": "A bankkezelési díj", "isCorrect": false}, {"id": "b2f64a89-3f73-4bb5-b520-1f69ca4c99a1", "text": "A büntetés", "isCorrect": false}, {"id": "7641fb79-4bfd-4ceb-89a6-3fc7b92cfcb9", "text": "A fizetett adó", "isCorrect": false}], "timeLimit": 15}, {"id": "dd027017-4b4b-449f-b692-dd3174877b32", "text": "Ha 100 000 Ft-ot beteszünk a bankba 5%-os éves kamatra, hány Ft kamatot kapunk 1 év múlva? (100000 * 0,05)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5000"}, {"id": "d2f8d491-4bde-4eff-af5b-7b1ef94be076", "text": "Mennyi pénzünk lesz a bankban az 1 év letelte után a 100 000 Ft betét és a 5000 Ft kamat összegeként?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "105000"}, {"id": "6abead5e-432c-4f90-bfbc-8db77cde1218", "text": "A futamidő az az időtartam, ameddig a pénzünket a bankban lekötjük.", "type": "true-false", "options": [{"id": "1e38696d-b4c8-4d62-8407-ac0409abddb3", "text": "Igaz", "isCorrect": true}, {"id": "6f558084-3b00-4c0f-b710-7fa24307371f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c949600c-3f5a-4bc6-aa8a-f39306d69f0d", "text": "A hitel felvételekor nekünk kell kamatot fizetnünk a banknak a kölcsönzött pénzért.", "type": "true-false", "options": [{"id": "b982fd58-0a59-4ccb-8458-d9768e566777", "text": "Igaz", "isCorrect": true}, {"id": "c2202870-18f3-4929-a5e7-e9f33407e886", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "cdbfc81d-19f5-4ed0-8138-7a7a97aa1bda", "text": "A megtakarítás segít a váratlan kiadások fedezésében és jövőbeli célok megvalósításában.", "type": "true-false", "options": [{"id": "f36bc792-d4fd-4137-84f4-37d7a2bb8846", "text": "Igaz", "isCorrect": true}, {"id": "0c65a82b-9558-49d1-8db6-395a2215afa5", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "046f7c97-7335-401c-9a24-870552280a61", "text": "Mennyi 200 000 Ft 10%-os éves kamata 1 évre?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20000"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('b63ae7f7-552a-4da1-be8a-748f30a72454', '21feff02-016d-46e2-bb9d-c27495133b1b', '129. óra: Mindennapi pénzügyeink II.', 'Devizák, valutavételi és -eladási árfolyam, valutaváltás.', 'Matematika', '6. osztály', 'Mindennapi pénzügyeink', '[{"id": "23732d73-56ae-45eb-abba-7ad5d9df50d1", "text": "Mit jelent a valuta és deviza árfolyama?", "type": "multiple-choice", "options": [{"id": "5f50d1a5-e26b-459a-9f87-557431d1139a", "text": "Egy külföldi pénznem (pl. Euró, Dollár) ára hazai pénzben (Ft-ban)", "isCorrect": true}, {"id": "c366f58a-cb61-4666-961b-bdc7e17f78d4", "text": "A bankjegy színe", "isCorrect": false}, {"id": "658819bb-2703-4729-8268-6c235babbb68", "text": "A pénz súlya", "isCorrect": false}, {"id": "e330838b-ee9c-4737-a19a-8a3fc078d53e", "text": "A bank nyitvatartása", "isCorrect": false}], "timeLimit": 15}, {"id": "bf43e449-86d1-4fe4-822f-4861f52c023e", "text": "Ha 1 Euró (EUR) eladási árfolyama 400 Ft, hány Ft-ba kerül 50 Euró vásárlása? (50 * 400)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20000"}, {"id": "b86b3e44-65d0-43ae-96aa-618376be3264", "text": "Ha 100 Eurót váltunk át Ft-ra 400 Ft/EUR vételi árfolyamon, hány Ft-ot kapunk?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40000"}, {"id": "a92589fc-ea0d-4365-87ff-0a863c55d547", "text": "A bankok eladási árfolyama magasabb, mint a vételi árfolyam (ebből származik a váltási haszon).", "type": "true-false", "options": [{"id": "e8da5447-532e-4485-9ad1-c44ad9cfa8aa", "text": "Igaz", "isCorrect": true}, {"id": "6ea09be5-b82a-43f5-94de-329da763432f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "722effbd-0016-45b0-a170-94a2a4857aaf", "text": "Melyik a közös európai pénznem jele és neve?", "type": "multiple-choice", "options": [{"id": "fb62368f-0530-4798-a8c6-918eb7c62651", "text": "EUR (€) - Euró", "isCorrect": true}, {"id": "f85986c2-641f-4ca3-8b88-cac1fdeffded", "text": "USD ($) - Dollár", "isCorrect": false}, {"id": "81e2cf46-e2ca-462d-a231-42e6afdfa7b7", "text": "GBP (£) - Font", "isCorrect": false}, {"id": "966c81ef-cbc3-4e7a-85da-bd48f823c2f5", "text": "HUF (Ft) - Forint", "isCorrect": false}], "timeLimit": 15}, {"id": "3727ed3c-4433-42bd-b160-6bdc7e456d47", "text": "Külföldi utazás előtt érdemes tájékozódni a hivalatos árfolyamokról.", "type": "true-false", "options": [{"id": "76dd2ef8-e4db-4cad-aa75-70d6cd6967d9", "text": "Igaz", "isCorrect": true}, {"id": "3da8d019-85e4-40b3-b542-7739394df530", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "6d3d1eb4-d5a2-4e1c-97fd-4f757200bfaa", "text": "Hány Ft 10 Dollár (USD), ha 1 USD = 350 Ft?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3500"}]'::jsonb, true, NOW());